    {
      "chapter": 3,
      "text_ar": "ثم تكلم إرميا قائلاً: «أرجوك يا رب، اسمح لي أن أتكلم بحضرتك».",
      "verse": 6
    },
    {
      "chapter": 3,
      "text_ar": "فقال الرب: «تكلم يا مختاري إرميا».",
      "verse": 7
    },
    {
      "chapter": 3,
      "text_ar": "فقال إرميا: «يا رب، الآن نعلم أنك تسلم المدينة لأعدائها، وسيسبون الشعب إلى بابل.",
      "verse": 8
    },
    {
      "chapter": 3,
      "text_ar": "ماذا تريد مني أن أفعل بآنية القدس لخدمة الهيكل؟»",
      "verse": 9
    },
    {
      "chapter": 3,
      "text_ar": "فقال له الرب: «خذها واستودعها الأرض، قائلاً: "
      ,
      "verse": 10
    }
  ]
}
